"use client"

import React, { useMemo } from "react"
import dynamic from "next/dynamic"
import { Chip, Skeleton, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import type { HealthByName } from "../hooks/useSystemHealthPoll"
import { ARCHITECTURE_MODULE_MAP } from "../modules"
import { buildLiveScene } from "./scene"
import { buildFutureScene } from "./future-scene"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** The R3F canvas is heavy + client-only — lazy so it never ships in the RSC
 *  bundle and never mounts during SSR. */
const ArchitectureScene = dynamic(
    () => import("@/components/blocks/marketing/ArchitectureScene").then((mod) => mod.ArchitectureScene),
    {
        ssr: false,
        loading: () => <Skeleton className="h-[440px] w-full rounded-3xl @app-sm:h-[560px]" />,
    },
)

/** Which era the map shows: today's live system, or the future roadmap. */
export type ArchitectureEra = "present" | "future"

/** Props for {@link ArchitectureMap}. */
export interface ArchitectureMapProps extends WithClassNames<undefined> {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Currently selected node id — highlighted with a ring on the map. */
    selectedId: string
    /** Click-to-select a node — kept in sync with the rail via `?node=`. */
    onSelectNode: (id: string) => void
}

/**
 * The live 3D architecture ATLAS — one flat isometric board, no pods, no drill.
 * Two eras via a single toggle:
 *
 *  - **Present** (default): the live atlas — all 17 infra/external components
 *    (live status dot) PLUS the 10 feature modules the Core API splits into
 *    (neutral, no dot — no health probe exists for them). Selecting a module
 *    brightens the infra it runs on ({@link buildLiveScene}); selecting infra
 *    highlights it. Everything on one grid, one tile per node.
 *  - **Future**: the microservices roadmap (Coming soon — no live status).
 *
 * The `?node=` selection is shared with the rail + dissection panel. Every scene
 * builder is a pure data function fed i18n'd labels here.
 *
 * @param props - {@link ArchitectureMapProps}
 */
export const ArchitectureMap = ({ healthByName, selectedId, onSelectNode, className }: ArchitectureMapProps) => {
    const t = useTranslations("architecture")

    const [era, setEra] = React.useState<ArchitectureEra>("present")

    // stable per-scene i18n label bags (memoised on t so scene builders stay pure)
    const flatLabels = useMemo(
        () => ({
            checking: t("status.checking"),
            unknown: t("status.unknown"),
            degraded: t("status.degraded"),
            down: t("status.down"),
            client: t("map.client"),
            clientSub: t("map.clientSub"),
            gateway: t("map.gateway"),
            gatewaySub: t("map.gatewaySub"),
            moduleName: (id: string) => t(`module.${id}.name`),
            moduleSub: (id: string) => {
                const value = t(`module.${id}.sub`)
                return value || undefined
            },
        }),
        [t],
    )
    const futureLabels = useMemo(
        () => ({
            bus: t("future.bus"),
            busSub: t("future.busSub"),
            service: (key: string) => t(`future.${key}`),
        }),
        [t],
    )

    const data = useMemo(
        () => (era === "future" ? buildFutureScene(futureLabels) : buildLiveScene(healthByName, flatLabels, selectedId)),
        [era, healthByName, flatLabels, futureLabels, selectedId],
    )

    // nothing is selectable in the future (roadmap) scene
    const onSelect = (id: string) => {
        if (era === "future") return
        onSelectNode(id)
    }

    const highlightId = era === "future" ? undefined : selectedId

    const caption = era === "future"
        ? t("future.caption")
        : ARCHITECTURE_MODULE_MAP[selectedId]
            ? t("map.moduleHint")
            : t("map.atlasHint")

    return (
        <div className={cn("flex flex-col gap-3", className)}>
            {/* era switch (present ⇄ future) — no pod/layout toggle anymore */}
            <div data-principle="content-row" className="flex flex-wrap items-center justify-between gap-3">
                <TabsCard
                    variant="primary"
                    className="w-full max-w-xs"
                    leftTabs={{
                        selectedKey: era,
                        ariaLabel: t("view.eraAria"),
                        onSelectionChange: (key) => setEra(String(key) as typeof era),
                        items: [
                            { key: "present", label: t("view.present") },
                            { key: "future", label: t("view.future") },
                        ],
                    }}
                />
                {era === "future" ? (
                    <Chip size="sm" className="bg-accent-soft text-accent-soft-foreground">
                        <Chip.Label>{t("future.comingSoon")}</Chip.Label>
                    </Chip>
                ) : null}
            </div>

            <ArchitectureScene
                data={data}
                selectedId={highlightId}
                onSelectNode={onSelect}
                caption={caption}
            />
        </div>
    )
}

"use client"

import React from "react"
import { ScrollShadow, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ARCHITECTURE_COMPONENTS } from "../../constants"
import { ARCHITECTURE_MODULES } from "../../modules"
import type { HealthByName } from "../../hooks/useSystemHealthPoll"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "../../statusVisual"
import { StackH } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link ArchitectureMobileNav}. */
export interface ArchitectureMobileNavProps extends WithClassNames<undefined> {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Selected node id, mirrored to `?node=`. */
    selectedId: string
    /** Selects a node — shares state with {@link import("..").ArchitectureRail}. */
    onSelect: (id: string) => void
}

/** One selectable chip: icon + name + status dot. */
const NodeChip = ({
    name,
    icon: Icon,
    healthByName,
    selected,
    onSelect,
}: NodeChipProps) => {
    const state = resolveArchitectureStatus(name, healthByName)
    const visual = getArchitectureStatusVisual(state)
    return (
        <button
            type="button"
            aria-pressed={selected}
            onClick={onSelect}
            className={cn(
                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                selected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
            )}
        >
            <Icon aria-hidden className="size-4 shrink-0" />
            <Typography type="body-sm" className={selected ? "text-accent-soft-foreground" : undefined}>{name}</Typography>
            <span className={cn("size-2 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
        </button>
    )
}

/** One module chip: icon + name, NO status dot (modules have no health probe). */
const ModuleChip = ({
    id,
    icon: Icon,
    selected,
    onSelect,
}: ModuleChipProps) => {
    const t = useTranslations("architecture")
    return (
        <button
            type="button"
            aria-pressed={selected}
            onClick={onSelect}
            className={cn(
                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                selected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
            )}
        >
            <Icon aria-hidden className="size-4 shrink-0" />
            <Typography type="body-sm" className={selected ? "text-accent-soft-foreground" : undefined}>{t(`module.${id}.name`)}</Typography>
        </button>
    )
}

/**
 * Mobile counterpart of {@link import("..").ArchitectureRail}: below `lg` the
 * docs-style rail hides, so the component list folds into two horizontally
 * scrollable chip rows (own system, then external dependencies) above the map
 * — the master-detail mobile pattern (mirrors `PracticeMobileNav`). Reads/
 * writes the same `?node=` state as the rail, so the two stay in lockstep.
 *
 * @param props - {@link ArchitectureMobileNavProps}
 */
export const ArchitectureMobileNav = ({ healthByName, selectedId, onSelect, className }: ArchitectureMobileNavProps) => {
    const t = useTranslations("architecture")
    const ownComponents = ARCHITECTURE_COMPONENTS.filter((c) => c.group === "own")
    const externalComponents = ARCHITECTURE_COMPONENTS.filter((c) => c.group === "external")

    return (
        <div className={cn("flex flex-col gap-3 @app-lg:hidden", className)}>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.ownGroup")}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={ownComponents.map((component) => (
                            () => (
                                <NodeChip
                                    name={component.name}
                                    icon={component.icon}
                                    healthByName={healthByName}
                                    selected={selectedId === component.name}
                                    onSelect={() => onSelect(component.name)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.externalGroup")}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={externalComponents.map((component) => (
                            () => (
                                <NodeChip
                                    name={component.name}
                                    icon={component.icon}
                                    healthByName={healthByName}
                                    selected={selectedId === component.name}
                                    onSelect={() => onSelect(component.name)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={ARCHITECTURE_MODULES.map((module) => (
                            () => (
                                <ModuleChip
                                    id={module.id}
                                    icon={module.icon}
                                    selected={selectedId === module.id}
                                    onSelect={() => onSelect(module.id)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
        </div>
    )
}

type NodeChipProps = {
    name: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    healthByName: HealthByName | null
    selected: boolean
    onSelect: () => void
}
type ModuleChipProps = {
    id: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    selected: boolean
    onSelect: () => void
}

"use client"

import React, { useMemo } from "react"
import { Label, ListBox, ScrollShadow, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ARCHITECTURE_COMPONENTS } from "../constants"
import { ARCHITECTURE_MODULES } from "../modules"
import type { HealthByName } from "../hooks/useSystemHealthPoll"
import { MetricsInline } from "../MetricsInline"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "../statusVisual"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link ArchitectureRail}. */
export interface ArchitectureRailProps extends WithClassNames<undefined> {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Selected node id, mirrored to `?node=`. */
    selectedId: string
    /** Selects a node (rail row, map click, or mobile chip all call this). */
    onSelect: (id: string) => void
}

/** One rail row: icon + name/tagline + a live status dot WITH a text label —
 *  never color-only (a11y: dot + text, ≥3:1 contrast). Shared by both the
 *  "own" and "external" groups below. */
const ComponentRow = ({
    name,
    icon: Icon,
    healthByName,
}: ComponentRowProps) => {
    const t = useTranslations("architecture")
    const state = resolveArchitectureStatus(name, healthByName)
    const visual = getArchitectureStatusVisual(state)
    const metrics = healthByName?.[name]?.metrics
    return (
        <span data-principle="identity" className="flex w-full min-w-0 items-center gap-2">
            <Icon aria-hidden className="size-4 shrink-0 text-muted" />
            <span className="flex min-w-0 flex-1 flex-col">
                <Typography type="body-sm" weight="medium" className="min-w-0 truncate">
                    {name}
                </Typography>
                <Typography type="body-xs" color="muted" className="min-w-0 truncate">
                    {t(`rail.tagline.${name}`)}
                </Typography>
                {/* only components with a local Docker container carry metrics — a
                    row with none (judge0, ollama, mail, aiBalancer, external SaaS)
                    simply stays 2 lines, no fake placeholder line */}
                <MetricsInline metrics={metrics} className="text-xs text-muted" />
            </span>
            <span className={cn("flex shrink-0 items-center gap-2 rounded-full px-2 py-0", visual.chipClassName)}>
                <span className={cn("size-1.5 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
                <Typography type="body-xs" className="whitespace-nowrap">
                    {t(`status.${state}`)}
                </Typography>
            </span>
        </span>
    )
}

/** One module rail row: icon + name + one-line sub. NO status dot — modules
 *  have no health probe (honesty), so a green/gray dot would be fabricated. */
const ModuleRow = ({
    id,
    icon: Icon,
}: ModuleRowProps) => {
    const t = useTranslations("architecture")
    return (
        <span data-principle="identity" className="flex w-full min-w-0 items-center gap-2">
            <Icon aria-hidden className="size-4 shrink-0 text-muted" />
            <span className="flex min-w-0 flex-1 flex-col">
                <Typography type="body-sm" weight="medium" className="min-w-0 truncate">
                    {t(`module.${id}.name`)}
                </Typography>
                <Typography type="body-xs" color="muted" className="min-w-0 truncate">
                    {t(`module.${id}.sub`)}
                </Typography>
            </span>
        </span>
    )
}

/**
 * Desktop LEFT RAIL — the "docs-style" sidebar (pinned header + scroll region,
 * full rail height) listing every probed component, GROUPED into StarCi's own
 * system vs the external SaaS it depends on. Selecting a row drives the shared
 * `?node=` state (rail ⇄ map ⇄ dissection panel). Placed in the rail column by
 * the page shell; reads/writes URL state via the `onSelect` callback + the
 * `selectedId` prop (owned by the parent so the mobile chip row stays in sync
 * too).
 *
 * @param props - {@link ArchitectureRailProps}
 */
export const ArchitectureRail = ({ healthByName, selectedId, onSelect, className }: ArchitectureRailProps) => {
    const t = useTranslations("architecture")

    const ownComponents = useMemo(() => ARCHITECTURE_COMPONENTS.filter((c) => c.group === "own"), [])
    const externalComponents = useMemo(() => ARCHITECTURE_COMPONENTS.filter((c) => c.group === "external"), [])

    const onSelectionChange = (keys: Set<React.Key> | "all") => {
        if (keys === "all") return
        const key = [...keys][0]
        if (typeof key === "string") onSelect(key)
    }

    return (
        <div className={cn("relative flex min-h-0 min-w-0 flex-col gap-3 p-6", className)}>
            <ScrollShadow hideScrollBar className="-mx-1 min-h-0 min-w-0 flex-1 overflow-y-auto px-1" data-principle="control-pad">
                <div data-principle="card-caption" className="flex flex-col gap-3">
                    <div data-principle="sibling-stack" className="flex flex-col gap-2">
                        <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("rail.ownGroup")}</Label>
                        <ListBox
                            aria-label={t("rail.ownGroup")}
                            selectionMode="single"
                            selectedKeys={ownComponents.some((c) => c.name === selectedId) ? [selectedId] : []}
                            onSelectionChange={onSelectionChange}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {ownComponents.map((component) => (
                                <ListBox.Item
                                    key={component.name}
                                    id={component.name}
                                    textValue={component.name}
                                    className="cursor-pointer rounded-2xl px-3 py-2 data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft" data-principle="control-pad"
                                >
                                    <ComponentRow name={component.name} icon={component.icon} healthByName={healthByName} />
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    </div>

                    <div data-principle="sibling-stack" className="flex flex-col gap-2">
                        <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("rail.externalGroup")}</Label>
                        <ListBox
                            aria-label={t("rail.externalGroup")}
                            selectionMode="single"
                            selectedKeys={externalComponents.some((c) => c.name === selectedId) ? [selectedId] : []}
                            onSelectionChange={onSelectionChange}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {externalComponents.map((component) => (
                                <ListBox.Item
                                    key={component.name}
                                    id={component.name}
                                    textValue={component.name}
                                    className="cursor-pointer rounded-2xl px-3 py-2 data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft" data-principle="control-pad"
                                >
                                    <ComponentRow name={component.name} icon={component.icon} healthByName={healthByName} />
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    </div>

                    <div data-principle="sibling-stack" className="flex flex-col gap-2">
                        <Label className="px-1 text-xs text-muted" data-principle="control-pad">
                            {t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}
                        </Label>
                        <ListBox
                            aria-label={t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}
                            selectionMode="single"
                            selectedKeys={ARCHITECTURE_MODULES.some((m) => m.id === selectedId) ? [selectedId] : []}
                            onSelectionChange={onSelectionChange}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {ARCHITECTURE_MODULES.map((module) => (
                                <ListBox.Item
                                    key={module.id}
                                    id={module.id}
                                    textValue={module.id}
                                    className="cursor-pointer rounded-2xl px-3 py-2 data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft" data-principle="control-pad"
                                >
                                    <ModuleRow id={module.id} icon={module.icon} />
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    </div>
                </div>
            </ScrollShadow>
        </div>
    )
}

type ComponentRowProps = {
    name: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    healthByName: HealthByName | null
}
type ModuleRowProps = {
    id: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
}

import React from "react"
import { QuestionIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { QnaEntity } from "@/modules/types/entities/qna"
import type { CallerIdentity } from "@/components/frames/_identity"

/** This block's own identity, handed down to whichever card is standing in as its root (BLOCK-2). */
const IDENTITY: CallerIdentity = { tier: "block", component: "CourseFaq" }

/** All display text, already localized by the connected `CourseFaq`; a story passes i18n keys. */
export interface CourseFaqLabels {
    /** Section label — rendered by `LabeledCard` on every branch and by `LabeledAccordionCard` once content is showing. */
    label: string
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
}

/** Props for {@link _CourseFaq} — presentational; all data resolved, no fetch/store/i18n. */
export interface CourseFaqProps {
    /**
     * First load, nothing in hand → the loading branch shimmers in place. Owned by the connected
     * file (loading-and-skeleton.md's first-load formula). `LabeledCard`/`LabeledAccordionCard`
     * carry no `isSkeleton` of their own — see `missingSkeletonSupport` — so this swaps in
     * `Skeleton.Accordion` right where the accordion would sit, still co-located (not a parallel
     * skeleton tree/file).
     */
    isSkeleton?: boolean
    /** Settled with zero Q&A entries → the empty message (beats content, loses to loading). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` on the error branch. */
    onRetry?: () => void
    /** Q&A entries, already sorted by `sortIndex`; ignored while `isSkeleton`. */
    qnas?: Array<QnaEntity>
    labels: CourseFaqLabels
}

/**
 * FAQ section: the course Q&A pairs as an accordion (markdown answers) — removes a common
 * objection before the buy decision. Presentational half of {@link import("./index").CourseFaq}:
 * error beats a stale loading flag, empty only once settled. `LabeledAccordionCard` (the content
 * branch) owns its accordion frame + label itself, so unlike most blocks this does not thread a
 * single tree with `isSkeleton` — `LabeledCard`/`LabeledAccordionCard` take no `isSkeleton` prop
 * (`missingSkeletonSupport`), so the loading branch mirrors the shape with `Skeleton.Accordion`
 * inline instead, framed the same way the error/empty branches are. See `tiers/split.md` — the
 * connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link CourseFaqProps}
 */
const _CourseFaq = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    qnas = [],
    labels,
}: CourseFaqProps) => {
    // error beats a stale loading flag; empty only once settled (BLOCK-8 order: error → loading → empty → content).
    const body = (() => {
        if (error) {
            return (
                <LabeledCard label={labels.label} identity={IDENTITY}>
                    <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
                </LabeledCard>
            )
        }
        if (isSkeleton) {
            return (
                <LabeledCard label={labels.label} identity={IDENTITY}>
                    <Skeleton.Accordion items={3} />
                </LabeledCard>
            )
        }
        if (isEmpty) {
            return (
                <LabeledCard label={labels.label} identity={IDENTITY}>
                    <AsyncContentEmpty
                        icon={QuestionIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                    />
                </LabeledCard>
            )
        }

        // content — the accordion card IS the frame + owns its own label (LabeledAccordionCard).
        // WARNING LabeledAccordionCard takes no `identity` prop (unlike LabeledCard) and there is no
        // sibling frame here to carry it instead — this branch's root stays unowned (unownedRoot).
        return (
            <LabeledAccordionCard
                label={labels.label}
                items={qnas.map((qna) => ({
                    id: qna.id,
                    title: qna.question,
                    body: () => <MarkdownContent markdown={qna.answer} />,
                }))}
            />
        )
    })()

    return body
}

export { _CourseFaq }

import React from "react"
import type { ReactNode } from "react"
import { TrashIcon } from "@phosphor-icons/react"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCardPlaceholder } from "@/components/composites/cards/SurfaceCard"
import { MediaCard } from "@/components/blocks/cards/MediaCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Button } from "@/components/atoms/buttons/Button"
import { ChoiceSwitch } from "@/components/atoms/forms"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import type { CvDocument } from "@/modules/types/entities/cv"
import { CvHtmlDocument } from "@/components/blocks/cv/CvBlocksWorkspace/CvHtmlDocument"

/**
 * `_CvGallery` — the SRC TWIN, presentational half of the CvGalleryPage gallery block
 * (see `tiers/split.md`): typed props, already resolved; no fetch/store/i18n
 * (that's the connected half, `./index.tsx`). Renders the user's CvGalleryPage documents
 * as live scaled thumbnails; a click opens the dedicated editor. Layout:
 * optional {@link PageHeader} (standalone-page context only, gated on
 * `breadcrumb`) above a state switch — error → {@link AsyncContentError},
 * settled-empty → {@link AsyncContentEmpty}, otherwise the responsive card
 * grid (one {@link SurfaceCardPlaceholder} "create new" tile trailing the
 * real documents).
 */

/** How the open-editor overlay + delete/public-toggle row reads on one CvGalleryPage card. */
export interface CvGalleryDocument {
    /** Stable id — React key, delete/toggle targets. */
    id: string
    /** Already-resolved display label (the connected file falls back to "Untitled N"). */
    label: string
    /** Full block/style payload — feeds the scaled live thumbnail preview. */
    doc: CvDocument
    /** Whether this is the user's ONE public CvGalleryPage (single-public-per-user, BE-enforced). */
    isPublic: boolean
    /** `true` while this card's own public-toggle mutation is in flight. */
    isTogglingPublic: boolean
    /** Accessible name for the cover press target — already interpolated with the label. */
    editAriaLabel: string
    /** Opens this CvGalleryPage in the editor. */
    onOpen: () => void
    /** Removes this CvGalleryPage. */
    onDelete: () => void
    /** Flags/unflags this CvGalleryPage as the public one. */
    onTogglePublic: (isPublic: boolean) => void
}

/** All display text, already localized by the connected {@link CvGallery}; a story passes i18n keys. */
export interface CvGalleryLabels {
    /** Page title — only shown when {@link CvGalleryProps.breadcrumb} is passed. */
    pageTitle: string
    /** Page description under the title. */
    pageDescription: string
    /** Hover-reveal CTA pill printed over a card's thumbnail. */
    openEditor: string
    /** Accessible name for the per-card delete button. */
    deleteCta: string
    /** Label beside the per-card public-toggle switch. */
    publicToggle: string
    /** Hint line shown under a card's switch row while it IS the public CvGalleryPage. */
    publicHint: string
    /** Label on the trailing "create new" dashed tile. */
    createCta: string
    emptyTitle: string
    emptyHint: string
    /** Secondary link out of the empty state, toward the learner's courses. */
    emptyCoursesLinkCta: string
    /** Primary empty-state action label (same handler as the dashed tile). */
    createFirst: string
    errorTitle: string
    retry: string
}

/** Props for {@link _CvGallery} — presentational; all data resolved, no fetch/store/i18n. */
export interface CvGalleryProps {
    /** Breadcrumb row rendered above the title (standalone page context); omitted → no header at all. */
    breadcrumb?: ReactNode
    /** First load, nothing in hand → the grid shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero documents → the empty state. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). */
    error?: unknown
    /** Retry the failed fetch. */
    onRetry?: () => void
    /** The CvGalleryPage documents, in display order. */
    documents: Array<CvGalleryDocument>
    /** Creates a new CvGalleryPage — the dashed tile's press handler AND the empty state's primary action. */
    onCreate: () => void
    /** `true` while the create mutation is in flight — disables the dashed tile. */
    isCreating?: boolean
    /** Courses browse link — the empty state's secondary action. */
    coursesHref: string
    labels: CvGalleryLabels
}

/** How many placeholder tiles the loading grid shows — mirrors the real grid's usual row. */
const SKELETON_TILE_COUNT = 3

const CvGalleryCardCover = ({ item, labels }: CvGalleryCardCoverProps) => (
    <button
        type="button"
        onClick={item.onOpen}
        aria-label={item.editAriaLabel}
        className="group relative block h-52 w-full cursor-pointer overflow-hidden bg-white outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent"
