const CvGalleryCardFooter = ({ item, labels }: CvGalleryCardFooterProps) => (
    <StackV
        gap={3}
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="flex-action"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    justify="between"
                    items={[
                        () => (
                            <ChoiceSwitch
                                isSelected={item.isPublic}
                                isDisabled={item.isTogglingPublic}
                                onValueChange={item.onTogglePublic}
                                label={labels.publicToggle}
                            />
                        ),
                        () => (
                            <Button
                                isIconOnly
                                size="sm"
                                variant="ghost"
                                ariaLabel={labels.deleteCta}
                                prefixIcon={TrashIcon}
                                onPress={item.onDelete}
                            />
                        ),
                    ]}
                />
            ),
            ...(item.isPublic ? [() => (
                <Typography size="xs" color="muted" text={labels.publicHint} />
            )] : []),
        ]}
    />
)

/**
 * One CvGalleryPage card — a scaled live thumbnail that opens the editor, plus a
 * public-toggle switch and a delete button in the footer.
 */
const CvGalleryCard = ({ item, labels }: CvGalleryCardProps) => (
    <MediaCard
        cover={() => <CvGalleryCardCover item={item} labels={labels} />}
        title={item.label}
        footer={() => <CvGalleryCardFooter item={item} labels={labels} />}
    />
)

/** One dashed "add new" tile mirroring {@link SKELETON_TILE_COUNT} placeholder cards while loading. */
const SkeletonTile = () => <Box className="h-[19rem] rounded-3xl border border-default bg-surface" />

/**
 * The CvGalleryPage GALLERY (presentational) — the profile `?tab=cv` surface (and the standalone
 * `/profile/cv` page). See {@link CvGalleryProps} for the full state contract; the
 * connected `./index.tsx` owns the fetch, the mutations, and every `t()` call.
 *
 * @param props - {@link CvGalleryProps}
 */
export const _CvGallery = ({
    breadcrumb,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    documents,
    onCreate,
    isCreating = false,
    coursesHref,
    labels,
}: CvGalleryProps) => {
    // The empty state's own action slot: the same "create" handler as the dashed
    // tile, plus a secondary link out to the courses catalog — `AsyncContentEmpty`'s
    // `description` is a plain string (COMPOSITE-8), so the courses link can no
    // longer live INSIDE that sentence the way it used to; it now sits as its own
    // line below the primary button instead (missingVocabulary).
    const emptyAction: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            align="center"
            items={[
                () => <Button label={labels.createFirst} variant="tertiary" size="sm" onPress={onCreate} />,
                () => <Typography size="sm" isLink href={coursesHref} text={labels.emptyCoursesLinkCta} />,
            ]}
        />
    )

    const gridItems: Array<GridItem> = isSkeleton
        ? Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
            key: `skeleton-${index}`,
            content: SkeletonTile,
        }))
        : [
            ...documents.map((item): GridItem => ({
                key: item.id,
                content: () => <CvGalleryCard item={item} labels={labels} />,
            })),
            {
                key: "__create",
                content: () => (
                    <SurfaceCardPlaceholder
                        label={labels.createCta}
                        onPress={onCreate}
                        isDisabled={isCreating}
                    />
                ),
            },
        ]

    let body: ReactNode
    if (error) {
        body = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        body = <AsyncContentEmpty title={labels.emptyTitle} description={labels.emptyHint} action={emptyAction} />
    } else {
        body = <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="block-boundary" explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups." items={gridItems} />
    }

    return (
        <StackV
            gap={7}
            principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            identity={{ tier: "block", component: "CvGallery" }}
            items={[
                ...(breadcrumb ? [() => (
                    <PageHeader
                        breadcrumb={breadcrumb}
                        title={labels.pageTitle}
                        description={labels.pageDescription}
                    />
                )] : []),
                () => body,
            ]}
        />
    )
}

type CvGalleryCardCoverProps = { item: CvGalleryDocument; labels: CvGalleryLabels }
type CvGalleryCardFooterProps = { item: CvGalleryDocument; labels: CvGalleryLabels }
type CvGalleryCardProps = { item: CvGalleryDocument; labels: CvGalleryLabels }

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { ChangelogCategory } from "@/modules/api/graphql/queries/types/changelog-entries"

/** How many placeholder rows the co-located skeleton shows while entries load. */
const SKELETON_ROW_COUNT = 4

/**
 * Tailwind classes for each category chip. Style, not data — stays in the
 * presentational half; the connected file only resolves the chip's LABEL text.
 */
const CATEGORY_CLASS: Record<ChangelogCategory, string> = {
    [ChangelogCategory.Feature]: "bg-success/15 text-success-soft-foreground",
    [ChangelogCategory.Fix]: "bg-warning/15 text-warning-soft-foreground",
    [ChangelogCategory.Announcement]: "bg-secondary/15 text-secondary",
}

/** One render-ready row: dates/labels already resolved by the connected `ChangelogList`. */
export interface ChangelogListEntry {
    /** Entry id — used as the row key. */
    id: string
    /** Publish date, already locale-formatted. */
    formattedDate: string
    /** Category chip, or `undefined` when the entry carries none. */
    category?: ChangelogCategory
    /** Already-translated category label — paired with `category` (both or neither). */
    categoryLabel?: string
    /** Optional "read more" destination — present renders the title as a link. */
    linkUrl?: string
    /** Headline. */
    title: string
    /** Optional short body. */
    body?: string
}

/** All display text, already localized by the connected `ChangelogList`; a story passes i18n keys. */
export interface ChangelogListLabels {
    /** Section heading, shown as the `LabeledCard` label (framed) or the inline heading (flat). */
    title: string
    /** Error-branch title (settled fetch error, nothing in hand). */
    loadError: string
    /** Error-branch retry button label — paired with `onRetry`. */
    retry: string
}

/** Props for {@link _ChangelogList} — presentational; all data resolved, no fetch/store/i18n. */
export interface ChangelogListProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero entries and no error → the whole block hides (label/frame included). */
    isEmpty?: boolean
    /** Truthy → the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** The dated changelog rows, newest first. */
    entries?: Array<ChangelogListEntry>
    /**
     * When true, render inside a `LabeledCard` (title as a Label OUTSIDE the card) —
     * used on the DashboardPage Overview tab. Defaults to the flat heading + list.
     */
    framed?: boolean
    labels: ChangelogListLabels
}

/**
 * One placeholder row — mirrors a real row's shape (meta line + title + body) so the
 * loaded list does not jump in when it resolves (loading-and-skeleton.md). `SurfaceListCard`/
 * `SurfaceListCardItem` carry no `isSkeleton` of their own, so this hand-mirrors the row's
 * content right where it sits instead of pulling in a separate skeleton tree.
 */
const SkeletonRow = () => (
    <SurfaceListCardItem>
        <StackV gap={2} items={[
            () => (
                <StackH gap={2} items={[
                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                    () => <Skeleton className="h-4 w-16 shrink-0 rounded-full" />,
                ]} />
            ),
            () => <Skeleton.Typography type="body-sm" width="3/4" />,
            () => <Skeleton.Typography type="body-sm" width="1/2" />,
        ]} />
    </SurfaceListCardItem>
)

/** One real row: date + optional category chip, title (link when `linkUrl` is set), optional body. */
const EntryRow = ({ entry }: EntryRowProps) => {
    // local consts (not `entry.category` property reads) so narrowing survives into the
    // nested `items` closures below — TS drops property narrowing across a callback boundary.
    const { formattedDate, category, categoryLabel, linkUrl, title, body } = entry
    return (
        <SurfaceListCardItem>
            <StackV gap={2} items={[
                () => (
                    <StackH gap={2} items={[
                        () => <Typography size="xs" color="muted" text={formattedDate} />,
                        ...(category && categoryLabel ? [() => (
                            <span className={`rounded-full px-2 py-0 text-xs font-medium ${CATEGORY_CLASS[category]}`}>
                                {categoryLabel}
                            </span>
                        )] : []),
                    ]} />
                ),
                () => (linkUrl ? (
                    <Typography
                        size="sm"
                        weight="medium"
                        isLink
                        underlineOnHover
                        href={linkUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        text={title}
                    />
                ) : (
                    <Typography size="sm" weight="medium" text={title} />
                )),
                ...(body ? [() => <Typography size="sm" color="muted" text={body} />] : []),
            ]} />
        </SurfaceListCardItem>
    )
}

/**
 * GitHub-style "Latest from our changelog" list for the DashboardPage right rail — the
 * presentational half of {@link import("./index").ChangelogList}. Each row shows the
 * published date, an optional colored category chip and the title (linked when the
 * entry has a destination). Four states in the fixed order error → loading → empty →
 * content: `error` falls to the shared `AsyncContentError` frame; settled + empty +
 * no error hides the WHOLE block (label/frame included, unchanged behaviour); otherwise
 * the one row tree renders with `isSkeleton` threaded to every leaf, and placeholder
 * rows keep the SAME `SurfaceListCard` shape while shimmering (loading-and-skeleton.md).
 * See `tiers/split.md` — the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link ChangelogListProps}
 */
export const _ChangelogList = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    entries = [],
    framed = false,
    labels,
}: ChangelogListProps) => {
    // settled, no error, nothing to show → hide the whole block, label included (unchanged behaviour)
    if (!isSkeleton && !error && isEmpty) {
        return null
    }

    const list = error ? (
        <AsyncContentError title={labels.loadError} onRetry={onRetry} retryLabel={labels.retry} />
    ) : (
        <SurfaceListCard>
            {isSkeleton
                ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => <SkeletonRow key={index} />)
                : entries.map((entry) => <EntryRow key={entry.id} entry={entry} />)}
        </SurfaceListCard>
    )

    if (framed) {
        return (
            <LabeledCard
                frameless
                label={labels.title}
                identity={{ tier: "block", component: "ChangelogList" }}
            >
                {list}
            </LabeledCard>
        )
    }

    // flat: inline heading + list (legacy placement).
    return (
        <StackV
            gap={3}
            identity={{ tier: "block", component: "ChangelogList" }}
            items={[
                () => <Typography size="base" weight="semibold" text={labels.title} />,
                () => list,
            ]}
        />
    )
}

type EntryRowProps = { entry: ChangelogListEntry }

import React from "react"
import { CardsIcon as LayersIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import type { SkeletonProps } from "@/components/frames/_slot"
import { Box } from "@/components/frames/Box"
import { Split } from "@/components/frames/Split"

/** Already-localized text for {@link _FlashcardReview}; the connected `FlashcardReview` interpolates `dueCount`. */
export interface FlashcardReviewLabels {
    /** "N flashcards due today" row label. */
    due: string
    /** CTA button label, e.g. "Review 3". */
    startWithCount: string
}

/** Props for {@link _FlashcardReview} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewProps {
    /** First load, nothing in hand → the row shimmers in place (co-located). Owned by the connected `FlashcardReview`. */
    isSkeleton?: boolean
    /**
     * Settled with nothing to nudge about — zero cards due, or the fetch failed — so
     * the widget self-hides. The two are folded together deliberately: this SECONDARY
     * widget has no error message of its own, the same self-hide contract the old
     * `AsyncContent` had whenever `errorContent`/`emptyContent` were left unpassed.
     */
    isEmpty?: boolean
    /** Navigates into the dedicated review page. */
    onStartReview?: () => void
    labels: FlashcardReviewLabels
}

/**
 * Centre-column "flashcards due today" nudge — the presentational half of
 * {@link FlashcardReview}. Renders ONE row (icon + due-count label <-> "start
 * review" CTA), with `isSkeleton` threaded to both sides of the {@link Split}
 * so the shimmer mirrors the loaded shape (loading-and-skeleton.md).
 * Settled-and-empty (or a failed fetch) self-hides instead of showing a
 * message — this is a SECONDARY nudge, not a region with its own empty/error
 * voice. See `tiers/split.md` — the connected `FlashcardReview` owns the fetch
 * and resolves i18n.
 *
 * @param props - {@link FlashcardReviewProps}
 */
export const _FlashcardReview = ({
    isSkeleton = false,
    isEmpty = false,
    onStartReview,
    labels,
}: FlashcardReviewProps) => {
    // settled (not skeleton) + nothing to show → self-hide (no error/empty voice for this nudge)
    if (!isSkeleton && isEmpty) {
        return null
    }
    return (
        <Box principle="cell-pad" className="p-3"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            identity={{ tier: "block", component: "FlashcardReview" }}>
            <Split
                gap={3}
                isSkeleton={isSkeleton}
                start={({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        size="sm"
                        weight="medium"
                        prefixIcon={LayersIcon}
                        truncate
                        text={labels.due}
                        isSkeleton={isSkeleton}
                    />
                )}
                end={({ isSkeleton }: SkeletonProps) => (
                    <Button
                        variant="primary"
                        size="sm"
                        label={labels.startWithCount}
                        onPress={onStartReview}
                        isSkeleton={isSkeleton}
                    />
                )}
            />
        </Box>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    cn,
} from "@heroui/react"
import {
    useDashboardTabUrlSync,
} from "./hooks/useDashboardTabUrlSync"
import {
    DashboardTabsBar,
} from "./DashboardTabsBar"
import {
    DashboardIdentity,
} from "./DashboardIdentity"
import {
    OverviewTab,
} from "./OverviewTab"
import {
    ExploreTab,
} from "./ExploreTab"
import {
    CoursesTab,
} from "./CoursesTab"
import {
    CommunityTab,
} from "./CommunityTab"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { useDashboardTabStore } from "@/hooks/zustand/dashboardTab/store"
import { useRegisterNavbarBottomLayer } from "@/hooks/zustand/navbarBottomLayer/store"
import { Container } from "@/components/frames/Container"
import { RailShell } from "@/components/frames/RailShell"

/** Props for {@link DashboardPage}. */
export type DashboardPageProps = WithClassNames<undefined>

/**
 * Logged-in home — rebuilt on the proven PROFILE page layout: a tab strip rendered
 * as the navbar's bottom layer, then a centered 2-column body — left = the viewer's identity +
 * standing (bare, stable across tabs), right = the selected tab's content. Tabs:
 * Overview (cockpit) · Explore (feed) · Courses · Community. The open tab lives in
 * the shared store and mirrors `?tab=` (shareable); only the active panel mounts,
 * so each tab's leaf queries fetch lazily. Mobile stacks the identity then the
 * content (no rail, no drawer). `"use client"` for the tab store + URL sync.
 * @param props - optional className for the root element
 */
export const DashboardPage = ({
    className,
}: DashboardPageProps) => {
    useDashboardTabUrlSync()
    const tab = useDashboardTabStore((state) => state.tab)
    // the DashboardPage tab strip renders as the global Navbar's bottom layer
    const tabsNode = useMemo(() => <DashboardTabsBar />, [])
    useRegisterNavbarBottomLayer(tabsNode)

    // RailShell owns the identity<->content layout seam (stack -> row at md, gap-8).
    const rail = () => <DashboardIdentity />
    const body = () => {
        if (tab === "overview") {
            return (
                <div
                    id="DashboardPage-panel-overview"
                    role="tabpanel"
                    aria-labelledby="overview"
                >
                    <OverviewTab />
                </div>
            )
        }
        if (tab === "explore") {
            return (
                <div
                    id="DashboardPage-panel-explore"
                    role="tabpanel"
                    aria-labelledby="explore"
                >
                    <ExploreTab />
                </div>
            )
        }
        if (tab === "courses") {
            return (
                <div
                    id="DashboardPage-panel-courses"
                    role="tabpanel"
                    aria-labelledby="courses"
                >
                    <CoursesTab />
                </div>
            )
        }
        if (tab === "community") {
            return (
                <div
                    id="DashboardPage-panel-community"
                    role="tabpanel"
                    aria-labelledby="community"
                >
                    <CommunityTab />
                </div>
            )
        }
        return null
    }

    return (
        <div className={cn("flex w-full flex-col", className)}>
            {/* tab strip is registered as the Navbar bottom layer above (not here) */}
            <Container
                size="xl"
                padding={6}
                identity={{ tier: "block", component: "DashboardPage" }}
                body={() => (
                    <RailShell
                        at="md"
                        principle="layout-split"
                        explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                        rail={rail}
                        body={body}
                    />
                )}
            />
        </div>
    )
}

