"use client"

import { usePathname, useRouter, useSearchParams } from "next/navigation"

/**
 * The two top-level flashcard modes, each its own route slug. Named "quiz" (not
 * "interview") on purpose — this is a DIFFERENT feature from the separate AI
 * Mock Interview (`learn/mock-interview`); reusing "interview" here read as the
 * same feature and caused real confusion (teacher: "don't call it interview...
 * it'll get mixed up with the interview feature"). Matches the BE naming already
 * in place (`FlashcardQuizSessionEntity`/`completeFlashcardQuizSession`).
 */
export type FlashcardMode = "study" | "quiz"

/** URL slug per mode (English, reads in the path: `…/flashcards/review`). */
const MODE_SLUG: Record<FlashcardMode, string> = {
    study: "review",
    quiz: "quiz",
}

/**
 * URL-backed navigation for the flashcards surface. The MODE is a route segment
 * (`…/flashcards/review` | `…/flashcards/quiz`) so each mode is its own page
 * with a readable English slug. Both "Study cards" session kinds — a single deck or
 * the cross-deck due queue — now share ONE live shape,
 * `…/flashcards/review/sessions/<sessionId>` (teacher, 2026-07-11: "drop the deck,
 * just go with session" — no more `decks/<id>` route segment, superseding the
 * 2026-07-09 "deck rides its own segment" decision). `deckId` travels as a
 * query hint (`?deckId=`) instead: on the bare shim (`review?deckId=<id>`) it
 * says WHICH deck to start/resume; on the live sessioned URL it's a HINT so a
 * direct link/refresh still knows to resume the DECK-scoped session (not the
 * due one) — `useQueryMyInProgressFlashcardReviewSessionSwr` needs a deckId to
 * scope its lookup, there is no id-only "which session is this" query. The
 * cross-deck due session stays its own query marker (`?session=due`) on the
 * bare shim; once live it carries no `deckId` at all. The LEFT RAIL (rendered
 * by the learn layout) and the work PANE (the page) both read this hook -> one
 * source of truth across the layout<->page boundary.
 */
export const useFlashcardNav = () => {
    const router = useRouter()
    const pathname = usePathname()
    const params = useSearchParams()

    // the segment right after "flashcards" carries the mode slug; `…/flashcards`
    // (no slug) = study. Read it by position off the "flashcards" segment rather
    // than the LAST path segment, so the resumable `…/quiz/sessions/[id]` /
    // `…/review/sessions/[id]` routes (which have extra segments past the mode
    // slug) still resolve to the right mode.
    const segments = pathname.split("/")
    const flashcardsIndex = segments.indexOf("flashcards")
    const modeSegment = flashcardsIndex >= 0 ? segments[flashcardsIndex + 1] : undefined
    const mode: FlashcardMode = modeSegment === MODE_SLUG.quiz ? "quiz" : "study"
    // the flashcards root (everything up to and including the "flashcards" segment)
    const root =
        flashcardsIndex >= 0
            ? segments.slice(0, flashcardsIndex + 1).join("/")
            : pathname

    // `?deckId=` — the deck-review shim/resume hint, only meaningful in study mode.
    const deckId = mode === "study" ? params.get("deckId") : null
    const session = params.get("session")

    /** Build a flashcards URL: the mode's route + optional deck / session query hint. */
    const build = (
        nextMode: FlashcardMode,
        opts: { deck?: string | null; session?: string | null } = {},
    ): string => {
        const path = `${root}/${MODE_SLUG[nextMode]}`
        const qs = new URLSearchParams()
        if (opts.deck) {
            qs.set("deckId", opts.deck)
        }
        if (opts.session) {
            qs.set("session", opts.session)
        }
        const qsStr = qs.toString()
        return qsStr ? `${path}?${qsStr}` : path
    }

    return {
        /** Active mode (study | quiz). */
        mode,
        /** Deck-review shim/resume hint, or null (overview / due session / topic picker). */
        deckId,
        /** Active session marker (`"due"` = cross-deck due session). */
        session,
        /** Switch mode (its own route; clears any open deck / session). */
        goMode: (nextMode: FlashcardMode) => router.push(build(nextMode, {})),
        /** Start/resume a deck's review (resolve-or-start shim, `?deckId=`). */
        goDeck: (id: string) => router.push(build(mode, { deck: id })),
        /** Return the study pane to its overview (due + mastery). */
        goOverview: () => router.push(build("study", {})),
    }
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
    Background,
    BackgroundVariant,
    type Edge,
    type Node,
    type NodeMouseHandler,
    Panel,
    ReactFlow,
    ReactFlowProvider,
    useEdgesState,
    useNodesState,
    useReactFlow,
} from "@xyflow/react"
import { cn } from "@heroui/react"
import { useLocale } from "next-intl"
import { useRouter } from "next/navigation"
import { useReducedMotion } from "framer-motion"
import { useTheme } from "next-themes"
import {
    forceCollide,
    forceLink,
    forceManyBody,
    forceSimulation,
    forceX,
    forceY,
    type Simulation,
    type SimulationLinkDatum,
    type SimulationNodeDatum,
} from "d3-force"
import { pathConfig } from "@/resources/path"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { LANDING_TRACK_COURSE_SLUG } from "../constants"
import { CONCEPT_NODE_TYPE, type ConceptNodeData, ConceptNode } from "./ConceptNode"
import { ShuffleBeacon } from "./ShuffleBeacon"
import { KNOWLEDGE_EDGES, KNOWLEDGE_NODES, NODE_DEGREE, TRACK_CONFIG, bubbleRadius, type TrackKey } from "./data"

/** A d3-force simulation node (positions written back onto React Flow each tick). */
interface SimNode extends SimulationNodeDatum {
    id: string
    track: TrackKey
}

/** Initial React Flow nodes — seeded around the ANCHOR per track (3 colors, 3 triangle
 * corners), scattered over a small ring; the force then pulls each track back to its own
 * corner, while the space between corners blends together naturally. */
const buildInitialNodes = (): Node<ConceptNodeData>[] =>
    KNOWLEDGE_NODES.map((node, index) => {
        const cfg = TRACK_CONFIG[node.track]
        const angle = (index / KNOWLEDGE_NODES.length) * Math.PI * 2
        return {
            id: node.id,
            type: CONCEPT_NODE_TYPE,
            position: {
                x: cfg.anchorX + Math.cos(angle) * 130,
                y: cfg.anchorY + Math.sin(angle) * 130,
            },
            data: { label: node.label, track: node.track },
            draggable: true,
        }
    })

/** Edges — ALL are light connecting lines (solid, thin, faint — like sharding<->cdc); NO dashed, NO accent. */
const buildEdges = (): Edge[] =>
    KNOWLEDGE_EDGES.map((edge, index) => ({
        id: `e${index}`,
        source: edge.source,
        target: edge.target,
        type: "straight",
        style: { stroke: "var(--border)", strokeWidth: 1, strokeOpacity: 0.22 },
    }))

/** Per-node collide radius (px): bubble radius, but ≥ half the label's width (the label is
 * CENTER-aligned and overflows past the bubble horizontally) so labels don't overlap their
 * neighbors. The pad keeps the bubble cluster feeling airy. */
const COLLIDE_RADIUS = new Map(
    KNOWLEDGE_NODES.map((node) => {
        const r = bubbleRadius(NODE_DEGREE[node.id] ?? 1)
        const labelHalfWidth = node.label.length * 3.4
        return [node.id, Math.max(r, labelHalfWidth) + 14] as const
    }),
)

/** Inner flow (needs to be inside {@link ReactFlowProvider} for `useReactFlow`). */
const KnowledgeGraphFlow = () => {
    const router = useRouter()
    const locale = useLocale()
    const { resolvedTheme } = useTheme()
    const reduce = useReducedMotion()
    const { setCenter } = useReactFlow()

    const [nodes, setNodes, onNodesChange] = useNodesState<Node<ConceptNodeData>>(buildInitialNodes())
    const [edges, , onEdgesChange] = useEdgesState(buildEdges())
    const [selectedId, setSelectedId] = useState<string | null>(null)
    const nodeTypes = useMemo(() => ({ [CONCEPT_NODE_TYPE]: ConceptNode }), [])

    // Re-shuffle = give every node a random velocity kick + reheat the sim → nodes drift
    // out and re-settle into a fresh arrangement (the beacon countdown / tap fires this).
    const reshuffle = useCallback(() => {
        const simulation = simRef.current
        if (!simulation) {
            return
        }
        simNodesRef.current.forEach((simNode) => {
            simNode.fx = null
            simNode.fy = null
            simNode.vx = (Math.random() - 0.5) * 200
            simNode.vy = (Math.random() - 0.5) * 200
        })
        simulation.alpha(1).restart()
    }, [])

    const simRef = useRef<Simulation<SimNode, undefined> | null>(null)
    const simNodesRef = useRef<Map<string, SimNode>>(new Map())
    const draggingRef = useRef<string | null>(null)

    // Live force layout: a d3-force simulation drives node positions; each tick writes
    // positions back to React Flow. The 3 tracks gravitate to their own x-anchor (loose
    // clusters) while charge + collide spread nodes and links pull related ones together.
    useEffect(() => {
        const simNodes: SimNode[] = buildInitialNodes().map((rfNode) => ({
            id: rfNode.id,
            track: rfNode.data.track,
            x: rfNode.position.x,
            y: rfNode.position.y,
        }))
        const byId = new Map(simNodes.map((simNode) => [simNode.id, simNode]))
        simNodesRef.current = byId

        const simLinks: SimulationLinkDatum<SimNode>[] = KNOWLEDGE_EDGES.map((edge) => ({
            source: edge.source,
            target: edge.target,
        }))

        const simulation = forceSimulation(simNodes)
            .force("charge", forceManyBody().strength(-100))
            .force("link", forceLink<SimNode, SimulationLinkDatum<SimNode>>(simLinks).id((node) => node.id).distance(90).strength(0.12))
            .force("x", forceX<SimNode>((node) => TRACK_CONFIG[node.track].anchorX).strength(0.05))
            .force("y", forceY<SimNode>((node) => TRACK_CONFIG[node.track].anchorY).strength(0.05))
            .force("collide", forceCollide<SimNode>((node) => COLLIDE_RADIUS.get(node.id) ?? 44))
            .alphaDecay(0.035)
        simRef.current = simulation

        const writeBack = () => setNodes((current) => current.map((rfNode) => {
            if (rfNode.id === draggingRef.current) return rfNode
            const simNode = byId.get(rfNode.id)
            return simNode ? { ...rfNode, position: { x: simNode.x ?? 0, y: simNode.y ?? 0 } } : rfNode
        }))
        simulation.on("tick", writeBack)

        // Camera: pushed in close to the cluster's center (zoom 1.2, center 0,0) → the 3-color
        // core converges to fill the frame, edges get cropped → drag (pan) to explore = a natural map feel.
        const centre = (duration: number) => void setCenter(0, 0, { zoom: 1.2, duration })

        const fits: ReturnType<typeof setTimeout>[] = []
        if (reduce) {
            simulation.stop()
            simulation.tick(300)
            writeBack()
            fits.push(setTimeout(() => centre(0), 0))
        } else {
            fits.push(setTimeout(() => centre(500), 600))
        }

        return () => {
            simulation.stop()
            fits.forEach(clearTimeout)
        }
    }, [setCenter, reduce, setNodes])

    // Drag pins the node (fx/fy) and reheats the sim; release lets it flow back.
    const onNodeDragStart: NodeMouseHandler = useCallback((_, node) => {
        draggingRef.current = node.id
        const simNode = simNodesRef.current.get(node.id)
        if (simNode) {
            simNode.fx = node.position.x
            simNode.fy = node.position.y
        }
        simRef.current?.alphaTarget(0.3).restart()
    }, [])
    const onNodeDrag: NodeMouseHandler = useCallback((_, node) => {
        const simNode = simNodesRef.current.get(node.id)
        if (simNode) {
            simNode.fx = node.position.x
            simNode.fy = node.position.y
        }
    }, [])
    const onNodeDragStop: NodeMouseHandler = useCallback((_, node) => {
        draggingRef.current = null
        const simNode = simNodesRef.current.get(node.id)
        if (simNode) {
            simNode.fx = null
            simNode.fy = null
        }
        simRef.current?.alphaTarget(0)
    }, [])

    // Click toggles a concept's popover (blurb + CTA); clicking empty pane closes it.
    const onNodeClick: NodeMouseHandler = useCallback((_, node) => {
        setSelectedId((prev) => (prev === node.id ? null : node.id))
    }, [])
    const onPaneClick = useCallback(() => setSelectedId(null), [])
    // CTA inside the popover → flagship course that teaches the concept (grounded).
    const onOpenCourse = useCallback(
        (track: TrackKey) => router.push(pathConfig().locale(locale).course(LANDING_TRACK_COURSE_SLUG[track]).build()),
        [router, locale],
    )
    // Inject per-render UI state (selected + CTA handler) into node data for the custom node.
    const displayNodes = useMemo(
        () => nodes.map((node) => ({
            ...node,
            // lift the open node (+ its popover) above every other node
            zIndex: node.id === selectedId ? 1000 : 0,
            data: { ...node.data, selected: node.id === selectedId, onOpenCourse },
        })),
        [nodes, selectedId, onOpenCourse],
    )

    return (
        <ReactFlow
            nodes={displayNodes}
            onPaneClick={onPaneClick}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onNodeDragStart={onNodeDragStart}
            onNodeDrag={onNodeDrag}
            onNodeDragStop={onNodeDragStop}
            onNodeClick={onNodeClick}
            nodeTypes={nodeTypes}
            colorMode={resolvedTheme === "dark" ? "dark" : "light"}
            // @xyflow dark colorMode bakes a #141414 pane bg via this var — force it
            // transparent so the graph blends into the page (starfield shows through).
            style={{ backgroundColor: "transparent", "--xy-background-color": "transparent" } as React.CSSProperties}
            proOptions={{ hideAttribution: true }}
            nodesConnectable={false}
            elementsSelectable={false}
            minZoom={1.2}
            maxZoom={1.2}
            // FIXED zoom; ALLOW drag (pan) to explore — the cluster's edges get cropped = a natural feel
            zoomOnScroll={false}
            zoomOnPinch={false}
            zoomOnDoubleClick={false}
            preventScrolling={false}
            panOnDrag
            translateExtent={[[-1000, -820], [1000, 820]]}
        >
            <Background variant={BackgroundVariant.Dots} gap={22} size={1} className="opacity-40" />
            {/* DeFi-swap-style countdown beacon (bottom-left): auto-reshuffles the graph
                every 10s; tap it to reshuffle now. Signals the graph is live + interactive. */}
            <Panel position="bottom-left">
                <ShuffleBeacon onShuffle={reshuffle} />
            </Panel>
        </ReactFlow>
    )
}

